<?php
declare(strict_types=1);
$app=require dirname(__DIR__,3).'/bootstrap.php';$app['auth']->requireRole(['ADMIN']);$year=max(2000,min(2100,(int)($_GET['year']??date('Y'))));$statement=$app['pdo']->prepare('SELECT id FROM dbo.business_invoices WHERE fiscal_year=:year AND uniref IS NOT NULL ORDER BY id');$statement->execute(['year'=>$year]);$ids=array_map('intval',$statement->fetchAll(PDO::FETCH_COLUMN));$service=new App\Billing\InvoiceDocumentService($app['pdo'],$app['config'],new App\Document\DocumentStore(dirname(__DIR__,3).'/var/documents'));$pdf=$service->bulk($ids);header('Content-Type: application/pdf');header('Content-Disposition: attachment; filename="faturat-'.$year.'.pdf"');header('Content-Length: '.strlen($pdf));header('Cache-Control: private, no-store');echo $pdf;
